(function(){
'use strict';
let session=null,timer=null,fast=false,showLog=false;
const $=s=>document.querySelector(s);
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,id,cls='',disabled=false)=>`<button class="mesa-button ${cls}" id="${id}" ${disabled?'disabled':''}>${label}</button>`;
function stopTimer(){clearTimeout(timer);timer=null}
function leave(){stopTimer();const old=session;session=null;$('#mesaDemo')?.remove();document.body.style.overflow=old?.bodyOverflow||'';if($('.app'))$('.app').inert=old?.appInert||false;old?.onClose?.()}
function start({renderCard,onClose,count=4}={}){if(session)leave();const bodyOverflow=document.body.style.overflow,appInert=$('.app')?.inert||false;session={match:new TrucoEngine.Match({count}),renderCard,onClose,bodyOverflow,appInert};showLog=false;document.body.style.overflow='hidden';if($('.app'))$('.app').inert=true;const el=document.createElement('section');el.id='mesaDemo';el.className='mesa-demo';el.setAttribute('aria-label','Mesa de Truco de prueba');document.body.append(el);draw();$('#mesaExit').focus()}
function card(c){return session.renderCard([c.n===1?'As':c.n===10?'Sota':c.n===11?'Caballo':c.n===12?'Rey':String(c.n),c.s])}
function activePlayer(g){return g.pending?g.pending.responder:g.turn}
function draw(){if(!session)return;stopTimer();const g=session.match;const active=activePlayer(g);const thinking=g.phase==='playing'&&active!==0;const positions=g.count===2?[0,2]:[0,1,2,3];
 const seats=Array.from({length:g.count},(_,p)=>`<div class="mesa-seat pos-${positions[p]} ${p%2===0?'partner':''} ${active===p&&g.phase==='playing'?'active':''}"><span class="person-icon">${['PE','RI','TC','RD'][p]}</span><div><b>${safe(g.name(p))}</b><small>${p===g.mano?'Mano · ':''}${p===(g.mano+g.count-1)%g.count?'Pie · ':''}${active===p&&g.phase==='playing'?(g.pending?'Responde al canto':p===0?'Tu turno':'Pensando…'):p%2===0?'Tu equipo':'Rivales'}</small></div></div>`).join('');
 const piles=g.played.map((cs,p)=>`<div class="mesa-pile pos-${positions[p]}" aria-label="Cartas jugadas por ${safe(g.name(p))}">${cs.length?cs.map((c,i)=>`<div class="mesa-played" style="--i:${i}" title="Baza ${i+1}: ${c.n} de ${safe(c.s)}">${card(c)}<span class="baza-tag">${i+1}</span></div>`).join(''):`<div class="mesa-empty">${p===0?'Tu espacio':p===2?'Compañero':'Rival'}</div>`}</div>`).join('');
 const backs=g.hands.map((h,p)=>p?`<div class="mesa-backs pos-${positions[p]}" aria-label="${h.filter(Boolean).length} cartas ocultas">${h.filter(Boolean).map(()=>'<span class="mesa-back"></span>').join('')}</div>`:'').join('');
 const hand=g.hands[0].map((c,i)=>c?`<button class="mesa-hand-card" data-mesa-card="${i}" style="--tilt:${(i-1)*5}deg" ${g.canPlay(0)?'':'disabled'} aria-label="Jugar ${c.n} de ${safe(c.s)}">${card(c)}<span class="slot-number">${i+1}</span></button>`:`<div class="mesa-hand-empty">Jugada</div>`).join('');
 const status=g.phase==='baza-over'?'Baza completa · comparando las cartas…':g.phase==='hand-over'||g.phase==='match-over'?g.handResult:g.pending?`${g.name(g.pending.from)}: ${g.pending.kind==='envido'?'Envite a '+g.pending.amount:g.callName(g.pending.amount)} · ${active===0?'responde al canto':g.name(active)+' está pensando…'}`:active===0?'Tu turno: puedes cantar o elegir una de tus cartas.':g.name(active)+' está pensando…';
 $('#mesaDemo').innerHTML=`<header class="mesa-toolbar"><div class="mesa-brand">Truco Venezolano<small>MESA AZUL · PRUEBA CON BOTS</small></div><div class="mesa-toolbar-actions"><span class="mesa-preview-badge">${g.count===4?'POR PAREJAS':'MANO A MANO'}</span><label class="speed-label"><input id="mesaFast" type="checkbox" ${fast?'checked':''}>Prueba rápida</label>${button('Historial','mesaLog')}${button('⛶','mesaFullscreen')}${button('Salir','mesaExit')}</div></header><div class="mesa-stage"><div class="mesa-wood"><div class="mesa-cloth"><div class="mesa-watermark">TRUCO<small>VENEZOLANO</small></div></div></div>${seats}${backs}${piles}<div class="mesa-score"><div class="score-label">PARTIDA A 24 · ENTRADA A 12</div><div class="mesa-score-row"><div><strong>${g.scores[0]}</strong><small>TU EQUIPO · ${g.scores[0]>=12?'DENTRO':'FUERA'}</small></div><span style="color:#ffffff55">:</span><div><strong>${g.scores[1]}</strong><small>RIVALES · ${g.scores[1]>=12?'DENTRO':'FUERA'}</small></div></div><div class="bazas">Mano ${g.handNo} · ${g.phase==='hand-over'||g.phase==='match-over'?'Cierre tras '+g.results.length+' bazas':'Baza '+Math.min(g.results.length+1,3)+' / 3'} · Truco ${g.trucoValue}<br>${g.results.map((t,i)=>`${i+1}: ${t===null?'Parda':t===0?'Nosotros':'Rivales'}`).join(' · ')||'Abre '+safe(g.name(g.mano))}</div></div><div class="mesa-vira">VIRA${card(g.vira)}</div><div class="mesa-deck"><div class="mesa-back"></div>MAZO</div></div><div class="mesa-status ${thinking?'thinking':''}" role="status" aria-live="polite">${safe(status)}</div><footer class="mesa-foreground"><div class="mesa-controls">${button('Envido','mesaEnvido','',!g.canEnvido(0))}${button(g.callName(g.nextTruco()),'mesaTruco','',!g.canTruco(0))}${button('Ir al mazo','mesaFold','',!g.canPlay(0))}${button('Reglas de prueba','mesaHelp')}</div><div><div class="mesa-hand">${hand}</div><div class="mesa-hint">${g.canPlay(0)?'Pulsa la carta que quieres jugar':'Las cartas se habilitan al llegar tu turno'}</div></div><div class="mesa-meta"><b>Tú y tu compañero frente a frente.</b><br>Las cartas quedan en el espacio de cada jugador durante las tres bazas.<br>Rivales automáticos · sin dinero real.</div></footer>${showLog?`<aside class="mesa-history" aria-label="Historial de la mano"><b>Últimas jugadas</b>${g.history.slice(-16).reverse().map(s=>`<p>${safe(s)}</p>`).join('')}</aside>`:''}`;
 $('#mesaExit').onclick=leave;$('#mesaLog').onclick=()=>{showLog=!showLog;draw()};$('#mesaFullscreen').setAttribute('aria-label','Alternar pantalla completa');$('#mesaFullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#mesaDemo').requestFullscreen()}catch{notify('La mesa ya ocupa la ventana. Tu navegador no permite ocultar sus barras.')}};if($('#mesaFast'))$('#mesaFast').onchange=e=>{fast=e.target.checked;draw()};
 document.querySelectorAll('[data-mesa-card]').forEach(b=>b.onclick=()=>{if(g.play(0,+b.dataset.mesaCard))draw()});$('#mesaEnvido').onclick=()=>{g.call(0,'envido');draw()};$('#mesaTruco').onclick=()=>{g.call(0,'truco');draw()};$('#mesaFold').onclick=()=>confirmFold();$('#mesaHelp').onclick=help;
 if(g.phase==='match-over'||g.phase==='hand-over'){result();return}
 if(g.pending&&g.pending.responder===0){reply();return}
 if(g.phase==='baza-over'){schedule(()=>{g.resolveBaza();draw()},fast?200:1900);return}
 if(thinking)schedule(()=>{g.botAction();draw()},fast?150:3000+Math.floor(Math.random()*3001));
}
function schedule(fn,ms){stopTimer();const current=session;timer=setTimeout(()=>{timer=null;if(session===current)fn()},ms)}
function dialog(title,text,actions){const el=document.createElement('div');el.className='mesa-overlay';el.innerHTML=`<section class="mesa-dialog" role="dialog" aria-modal="true" aria-labelledby="mesaDialogTitle"><div class="eyebrow">MESA DE PRUEBA</div><h2 id="mesaDialogTitle">${title}</h2>${text}<div class="mesa-dialog-actions">${actions}</div></section>`;$('#mesaDemo').append(el);el.querySelector('button')?.focus();return el}
function reply(){const g=session.match,q=g.pending;const en=q.kind==='envido';const canRaise=en||q.amount<24;dialog(en?'Te cantaron envite':g.callName(q.amount),`<p>${safe(g.name(q.from))} propone ${q.amount} tantos. Tu turno para responder.</p>${en?'<p>Para subir: quiero y <input id="mesaRaiseAmount" type="number" min="1" max="24" value="2" aria-label="Tantos adicionales"> tantas más.</p>':''}<p class="mesa-help-note">Al rechazar se anotan ${q.decline} tantos. El juego espera tu respuesta.</p>`,button('Quiero','mesaYes','gold')+button('No quiero','mesaNo')+(canRaise?button(en?'Quiero y tantas más':g.callName(({3:6,6:9,9:24})[q.amount]),'mesaRaise'):''));$('#mesaYes').onclick=()=>{g.respond(0,'yes');draw()};$('#mesaNo').onclick=()=>{g.respond(0,'no');draw()};if($('#mesaRaise'))$('#mesaRaise').onclick=()=>{const extra=en?Number($('#mesaRaiseAmount').value):2;if(!g.respond(0,'raise',extra))return;draw()}}
function result(){const g=session.match,over=g.phase==='match-over';dialog(over?(g.matchWinner===0?'¡Ganó tu equipo!':'Ganaron los rivales'):'Fin de la mano',`<p>${safe(g.handResult||g.message)}</p>${g.envidoAward?`<p>${safe(g.envidoAward.text)} · ${g.envidoAward.points} tantos.</p>`:''}<p><strong>Tu equipo ${g.scores[0]} — ${g.scores[1]} Rivales</strong></p><p class="mesa-help-note">Las cartas permanecen sobre la mesa hasta el siguiente reparto.</p>`,button(over?'Nueva partida':'Siguiente mano','mesaNext','gold')+button('Ver cartas','mesaInspect')+button('Salir','mesaResultExit'));$('#mesaNext').onclick=()=>{if(over)session.match=new TrucoEngine.Match({count:g.count});else g.nextHand();draw()};$('#mesaResultExit').onclick=leave;$('#mesaInspect').onclick=()=>{$('.mesa-overlay').remove();const continueBtn=document.createElement('button');continueBtn.className='mesa-button gold';continueBtn.id='mesaContinue';continueBtn.textContent=over?'Nueva partida':'Siguiente mano';$('.mesa-controls').append(continueBtn);continueBtn.onclick=()=>{if(over)session.match=new TrucoEngine.Match({count:g.count});else g.nextHand();draw()}}}
function confirmFold(){stopTimer();dialog('¿Ir al mazo?',`<p>Los rivales sumarán ${session.match.trucoValue} tantos por el truco. El envite pendiente de anotación se resolverá primero.</p>`,button('Seguir jugando','mesaCancel','gold')+button('Ir al mazo','mesaConfirmFold'));$('#mesaCancel').onclick=draw;$('#mesaConfirmFold').onclick=()=>{session.match.endHand(1,session.match.trucoValue,'Tu equipo fue al mazo');draw()}}
function help(){stopTimer();dialog('Cómo probar la mesa',`<p>Te sientas abajo. Tu compañero está enfrente; los rivales, a los lados. El turno recorre los asientos: tú → izquierda → compañero → derecha. La mano rota en cada reparto.</p><p>Elige una de tus tres cartas. Puedes envidar antes de tu primera carta; los cantos pendientes bloquean las cartas hasta recibir respuesta. El ganador abre la siguiente baza y la mano termina en dos o tres bazas, según el resultado.</p><p>Partida a 24. La etiqueta cambia de Fuera a Dentro al llegar a 12. Truco: 3, Retruco: 6, Vale 9: 9 y Vale juego: 24.</p><p class="mesa-help-note">Demo local con bots, sin multijugador online. Flor automática: 3 tantos, comparada sin subidas si hay flores rivales. La entrada a 12 es un umbral de marcador; no cambia el cálculo del envite en esta prueba. No incluye falta envido, contra flor ni envite intercalado al responder un truco.</p>`,button('Volver a la mesa','mesaHelpClose','gold'));$('#mesaHelpClose').onclick=draw}
function notify(text){stopTimer();dialog('Pantalla completa',`<p>${safe(text)}</p>`,button('Continuar','mesaNotice','gold'));$('#mesaNotice').onclick=draw}
window.MesaDemo={start,leave};
})();
